    let project = window.find("Project").bounds();
    let appearance = window.find("Appearance").bounds();
    assert_eq!(
        appearance.left() - project.right(),
        gpui_kit::px(12.),
        "something sits between Project's group {project:?} and Application's {appearance:?}"
    );
})
.unwrap();
